const BRIGHT = { rust: "#f2a07b", github: "#e6edf3", django: "#44b78b", sqlite: "#4aa8e0", nextdotjs: "#e6edf3", nodedotjs: "#6cc24a", cplusplus: "#659ad2", neovim: "#57a143", linux: "#fcc624", docker: "#2496ed" };
const STACK = [
  ["Languages", [["typescript", "TypeScript"], ["javascript", "JavaScript"], ["python", "Python"], ["php", "PHP"], ["kotlin", "Kotlin"], ["cplusplus", "C++"], ["rust", "Rust"]]],
  ["Frameworks", [["react", "React"], ["nextdotjs", "Next.js"], ["nodedotjs", "Node.js"], ["nestjs", "NestJS"], ["laravel", "Laravel"], ["tailwindcss", "Tailwind"], ["fastapi", "FastAPI"], ["django", "Django"]]],
  ["Data & infra", [["postgresql", "PostgreSQL"], ["mongodb", "MongoDB"], ["redis", "Redis"], ["sqlite", "SQLite"], ["docker", "Docker"], ["aws", "AWS", "#ff9900"]]],
  ["Tools", [["git", "Git"], ["github", "GitHub"], ["linux", "Linux"], ["gnubash", "Bash"], ["neovim", "NeoVim"], ["vscode", "VS Code", "#3b9be8"], ["figma", "Figma"]]],
];
export function techStack() {
  const rowH = 86, x0 = 168, pitch = 80;
  const rows = STACK.map(([title, items], r) => { const y = 92 + r * rowH;
    return `${text(28, y + 42, title, { size: 14, weight: 700 })}${text(28, y + 58, `${items.length} tools`, { size: 11, fill: C.dim })}` + items.map(([key, name, fallback], i) => {
      const x = x0 + i * pitch, ic = ICONS[key], col = BRIGHT[key] || ic?.hex || fallback || C.mute, glyph = ic
        ? `<g transform="translate(${x + 20},${y + 10}) scale(1.2)" fill="${col}"><path d="${ic.d}"/></g>`
        : text(x + 34, y + 38, key === "vscode" ? "VS" : key.toUpperCase(), { size: 15, weight: 800, fill: col, anchor: "middle" });
      return `<g><animateTransform attributeName="transform" type="translate" values="0 0;0 -3;0 0" dur="${(3 + (i * 7 + r * 3) % 5 * 0.4).toFixed(1)}s" begin="${((i + r) % 4 * 0.3).toFixed(1)}s" repeatCount="indefinite"/><rect x="${x}" y="${y}" width="68" height="70" rx="14" fill="#151a24" stroke="#232b38"/>${glyph}${text(x + 34, y + 62, name, { size: 11, fill: C.dim, anchor: "middle" })}</g>`; }).join(""); }).join("");
  return card(W, 92 + STACK.length * rowH + 14, `${header(W, "tech stack", "Tools I build with", "languages, frameworks, data and daily tools")}${rows}`);
}

// 10. CONNECT HEADER -----------------------------------------------------------------------------------------------------
export function connect() {
  return card(W, 92, `${header(W, "connect", "Let's build something together", "rezwoan.codes")}`);
}
